; EXODUS.BIN: Ultima III (Origin 1983, PC version by James R. Van Artsdalen).
; Generated by tools/gen.py; tools/build.py builds it (MASM, LINK, then the image from 0100).
; DUNMOVE: dungeon: traps, darkness, turning, advancing (8190-84DB).
;
; The Get Chest command (surface and dungeon) with its four traps, the hurt-the-whole-party routine
; shared by traps and cannon fire, and the dungeon's own main loop: EnterDungeon starts it,
; DungeonLoop reads a key (a Pass after 5 seconds) and dispatches through DungeonKeys /
; DungeonCmds (ACTIONS 7708/774A), and every command ends in DungeonTurnEnd: moves, food,
; the torch burns down, the view is redrawn, then the cell under the party may start a fight or an
; event (DUNEVENT, through the table at DungeonEventCmds). The movement commands are here too: Klimb,
; Descend, turn right/left, Advance, Retreat.
; Data used: PlayerXY (x, y on the 16 x 16 level), Facing (0 north, 1 east, 2 south, 3 west),
; DungeonLevel (0-7), LightOn (torch turns left: Ignite sets 0FFh, each turn takes one).
; Dungeon cells (DungeonCell returns AL and BX = its address): 00 floor, 01-08 events, 10h ladder
; up, 20h ladder down, 40h chest (also left where a fight started), 80h wall, A0h/C0h door kinds.
CODE SEGMENT BYTE PUBLIC
ASSUME CS:CODE, DS:CODE, ES:CODE, SS:CODE
EXTRN PutChar:NEAR
EXTRN Random:NEAR
EXTRN KeyReady:NEAR
EXTRN ReadKey:NEAR
EXTRN Sound:NEAR
EXTRN Location:BYTE
EXTRN PartySize:BYTE
EXTRN Players:BYTE
EXTRN PlayerXY:BYTE
EXTRN LightOn:BYTE
EXTRN DungeonLevel:BYTE
EXTRN MainLoop:NEAR
EXTRN PrintMsg:NEAR
EXTRN ClearView:NEAR
EXTRN MapCellAddr:NEAR
EXTRN DungeonCell:NEAR
EXTRN Facing:BYTE
EXTRN DexRoll:NEAR
EXTRN PrintLevelHead:NEAR
EXTRN ExitToSosaria:NEAR
EXTRN HurtPlayer:NEAR
EXTRN IsUp:NEAR
EXTRN CheckAllOut:NEAR
EXTRN FlushKeys:NEAR
EXTRN AskPlayer:NEAR
EXTRN StatusLine:NEAR
EXTRN PartyUpkeep:NEAR
EXTRN FlashPlayer:NEAR
EXTRN FacingDxTbl:BYTE
EXTRN FacingDyTbl:BYTE
EXTRN DungeonEventCmds:BYTE
EXTRN DungeonKeys:BYTE
EXTRN DungeonCmds:BYTE
EXTRN DungeonPrompts:BYTE
EXTRN MsgItsDark:BYTE
EXTRN MsgTrapEvaded:BYTE
EXTRN MsgAcidTrap:BYTE
EXTRN MsgPoisonTrap:BYTE
EXTRN MsgBombTrap:BYTE
EXTRN MsgGasTrap:BYTE
EXTRN MsgWhat:NEAR
EXTRN MsgInvalidMove:NEAR
EXTRN MsgNotHere:NEAR
EXTRN MsgIncapacitated:NEAR
EXTRN AddMoves:NEAR
EXTRN ChestLoot:NEAR
EXTRN FoeTile:BYTE
EXTRN StartCombat:NEAR
EXTRN DrawDungeon:NEAR
PUBLIC CmdGetChest
PUBLIC DamageParty
PUBLIC EnterDungeon
PUBLIC DungeonLoop
PUBLIC DungeonTurnEnd
PUBLIC CmdKlimb
PUBLIC CmdDescend
PUBLIC CmdTurnRight
PUBLIC CmdTurnLeft
PUBLIC CmdNotDungeon
PUBLIC CmdAdvance
PUBLIC CmdRetreat
;------------------------------------------------------------------------------
; CmdGetChest: Get Chest, in both the surface and the dungeon tables. SI = prompt.
; Asks the player; on the surface the cell must be a chest (24h-27h: the low two bits say what
; it stood on: 0 floor, 1 grass, 2 brush, 3 forest), in a dungeon cell 40h. The chest goes, then
; half the time a trap springs (acid, poison, gas or bomb; see GetChest_Trap), and in any case
; ChestLoot (EQUIP 80D9) gives the player at DI gold and maybe a weapon or armour.
;------------------------------------------------------------------------------
CmdGetChest:	call PrintMsg	;@8190
	call AskPlayer	; ZF: Esc; else AL = 1-4, BX = record	;@8193
	je GetChest_Done	;@8196
	dec al	;@8198
	mov bp, ax	; BP = player number 0-3	;@819A
	mov di, bx	; DI = the player's record	;@819C
	call IsUp	;@819E
	jne GetChest_Incap	;@81A1
	mov bx, word ptr PlayerXY	;@81A3
	cmp byte ptr Location, 1	; in a dungeon?	;@81A7
	je GetChest_Dungeon	;@81AC
	call MapCellAddr	;@81AE
	cmp al, 24h	; chest tiles 24h-27h (shape 9 times 4)	;@81B1
	jb GetChest_NotHere	;@81B3
	cmp al, 27h	;@81B5
	ja GetChest_NotHere	;@81B7
	and al, 3	; low bits: the tile it stood on	;@81B9
	shl al, 1	;@81BB
	shl al, 1	;@81BD
	jne GetChest_SetTile	; 1-3: grass 04h, brush 08h, forest 0Ch	;@81BF
	mov al, 20h	; 0: floor (shape 8)	;@81C1
GetChest_SetTile:	mov byte ptr [bx], al	;@81C3
	jmp short GetChest_Open	;@81C5
GetChest_Dungeon:	call DungeonCell	;@81C7
	cmp al, 40h	; 40h: chest in a dungeon	;@81CA
	jne GetChest_NotHere	;@81CC
	mov byte ptr [bx], 0	; becomes floor	;@81CE
GetChest_Open:	mov dh, 0FFh	;@81D1
	call Random	;@81D3
	shl dl, 1	; half the time: a trap	;@81D6
	jb GetChest_Trap	;@81D8
	call ChestLoot	; gold etc. for the player at DI	;@81DA
GetChest_Done:	jmp MainLoop	;@81DD
GetChest_NotHere:	jmp MsgNotHere	;@81E0
GetChest_Incap:	jmp MsgIncapacitated	;@81E3
; Which trap: AL and DL two random bytes. (DL & AL & 3) = 0 gives acid (9 times in 16); else
; AL = 1 poison, AL = 2 gas, others bomb. AL is the whole random byte, not DL, so poison and gas
; come about once in 256 (probably meant DL).
GetChest_Trap:	call Random	;@81E6
	mov al, dl	;@81E9
	call Random	;@81EB
	and dl, al	;@81EE
	and dl, 3	;@81F0
	je GetChest_Acid	;@81F3
	cmp al, 1	;@81F5
	je GetChest_Poison	;@81F7
	cmp al, 2	;@81F9
	je GetChest_Gas	;@81FB
	jmp GetChest_Bomb	;@81FD
GetChest_Gas:	lea si, MsgGasTrap	; "Gas trap!"	;@8200
	call PrintMsg	;@8204
	call TryEvadeTrap	;@8207
	cmp al, 0	; AL = 0: evaded	;@820A
	jne GetChest_GasAll	;@820C
	jmp GetChest_Gold	;@820E
GetChest_GasAll:	lea bx, Players	; gas poisons every player who is up	;@8211
	mov cl, 0	;@8215
GetChest_GasLoop:	call IsUp	;@8217
	jne GetChest_GasNext	;@821A
	mov al, cl	;@821C
	call FlashPlayer	; flash the player's status line	;@821E
	mov al, 0F7h	;@8221
	call Sound	; hit sound	;@8223
	mov al, cl	;@8226
	call FlashPlayer	;@8228
	mov byte ptr [bx+11h], 50h	; status 'P' poisoned	;@822B
GetChest_GasNext:	add bx, 40h	; next record	;@822F
	inc cl	;@8232
	cmp cl, byte ptr PartySize	;@8234
	jb GetChest_GasLoop	;@8238
	jmp short GetChest_Gold	;@823A
GetChest_Acid:	lea si, MsgAcidTrap	; "Acid trap!"	;@823C
	call PrintMsg	;@8240
	call TryEvadeTrap	;@8243
	cmp al, 0	;@8246
	je GetChest_Gold	;@8248
	mov ax, bp	;@824A
	call FlashPlayer	;@824C
	mov al, 0F7h	;@824F
	call Sound	;@8251
	mov ax, bp	;@8254
	call FlashPlayer	;@8256
	mov dl, 0FFh	; (DH is still 0FFh: Random up to 0FEh)	;@8259
	call Random	;@825B
	and dl, 37h	; damage 00-37 BCD	;@825E
	mov al, dl	;@8261
	mov bx, di	;@8263
	call HurtPlayer	; subtract AL (BCD) from the hit points	;@8265
	call StatusLine	;@8268
	jmp short GetChest_Gold	;@826B
GetChest_Poison:	lea si, MsgPoisonTrap	; "Poison trap!"	;@826D
	call PrintMsg	;@8271
	call TryEvadeTrap	;@8274
	cmp al, 0	;@8277
	je GetChest_Gold	;@8279
	mov ax, bp	;@827B
	call FlashPlayer	;@827D
	mov al, 0F7h	;@8280
	call Sound	;@8282
	mov ax, bp	;@8285
	call FlashPlayer	;@8287
	mov byte ptr [di+11h], 50h	; status 'P' poisoned	;@828A
	jmp short GetChest_Gold	;@828E
GetChest_Bomb:	lea si, MsgBombTrap	; "Bomb trap!"	;@8290
	call PrintMsg	;@8294
	call TryEvadeTrap	;@8297
	cmp al, 0	;@829A
	je GetChest_Gold	;@829C
	call DamageParty	; everyone is hurt	;@829E
GetChest_Gold:	call ChestLoot	; the chest's gold anyway	;@82A1
	call StatusLine	;@82A4
	jmp MainLoop	;@82A7
;------------------------------------------------------------------------------
; TryEvadeTrap: the dexterity check of the player at DI (ITEMS 5B85, ZF set = evaded); if he
; evades, print "Trap evaded!" and return AL = 0, else AL unchanged (AL = 0 on entry also
; counts as evaded, silently). Saves flags, BX, SI.
;------------------------------------------------------------------------------
TryEvadeTrap:	pushf	;@82AA
	push bx	;@82AB
	push si	;@82AC
	mov bx, di	;@82AD
	call DexRoll	; ZF set: evaded	;@82AF
	jne TryEvadeTrap_Done	;@82B2
	lea si, MsgTrapEvaded	; "Trap evaded!"	;@82B4
	call PrintMsg	;@82B8
	mov al, 0FAh	; rise sound	;@82BB
	call Sound	;@82BD
	mov al, 0	;@82C0
TryEvadeTrap_Done:	pop si	;@82C2
	pop bx	;@82C3
	popf	;@82C4
	ret	;@82C5
;------------------------------------------------------------------------------
; DamageParty: every player who is up takes (random & 77h) + (DungeonLevel + 1) * 8
; damage (BCD: 0-77 plus 8, 16, ... 64), with a flash and the hit sound. Used by the bomb trap,
; the dungeon trap cell, and on the surface by cannon fire (LOOP 1C5D, WORLD 2396), where
; DungeonLevel is whatever the last dungeon left. Saves all.
;------------------------------------------------------------------------------
DamageParty:	pushf	;@82C6
	push ax	;@82C7
	push bx	;@82C8
	push cx	;@82C9
	push dx	;@82CA
	lea bx, Players	;@82CB
	mov cl, 0	;@82CF
DamageParty_Loop:	call IsUp	;@82D1
	jne DamageParty_Next	;@82D4
	mov al, cl	;@82D6
	call FlashPlayer	; flash the status line	;@82D8
	mov al, 0F7h	;@82DB
	call Sound	; hit sound	;@82DD
	mov al, cl	;@82E0
	call FlashPlayer	;@82E2
	mov dh, 0FFh	;@82E5
	call Random	;@82E7
	and dl, 77h	; damage 00-77 BCD	;@82EA
	mov al, dl	;@82ED
	call HurtPlayer	; subtract from the hit points	;@82EF
	mov al, byte ptr DungeonLevel	;@82F2
	inc al	;@82F5
	shl al, 1	;@82F7
	shl al, 1	;@82F9
	shl al, 1	;@82FB
	call HurtPlayer	; then (level + 1) * 8 more	;@82FD
DamageParty_Next:	add bx, 40h	;@8300
	inc cl	;@8303
	cmp cl, byte ptr PartySize	;@8305
	jb DamageParty_Loop	;@8309
	call StatusLine	;@830B
	pop dx	;@830E
	pop cx	;@830F
	pop bx	;@8310
	pop ax	;@8311
	popf	;@8312
	ret	;@8313
;------------------------------------------------------------------------------
; EnterDungeon: reached after LOOP has loaded the dungeon file and DUNGEON.DAT: no
; torch, level 1 (0), the header line, a blank view, and on into the dungeon loop.
;------------------------------------------------------------------------------
EnterDungeon:	mov byte ptr LightOn, 0	;@8314
	mov byte ptr DungeonLevel, 0	;@8319
	call PrintLevelHead	; the "LVL" header (SHRINE 62FD)	;@831E
	call ClearView	;@8321
	jmp DungeonLoop	;@8324
;------------------------------------------------------------------------------
; DungeonLoop: the dungeon's main loop. Checks that someone is alive (PARTY 6C29), says
; "It's dark!" while no torch burns, then waits for a key for 5 seconds (a Pass when none
; comes), upper-cases it and jumps through DungeonCmds with SI = the command's prompt.
;------------------------------------------------------------------------------
DungeonLoop:	call CheckAllOut	; all dead? (does not come back then)	;@8327
	cmp byte ptr LightOn, 0	;@832A
	jne DungeonLoop_Prompt	;@832F
	lea si, MsgItsDark	; "It's dark!"	;@8331
	call PrintMsg	;@8335
DungeonLoop_Prompt:	mov al, 10h	; the prompt character	;@8338
	call PutChar	;@833A
	mov ah, 2Ch	; DOS get time: DH = seconds	;@833D
	int 21h	;@833F
	mov bl, dh	;@8341
	add bl, 5	; 5 seconds from now	;@8343
	cmp bl, 3Ch	;@8346
	jb DungeonLoop_Wait	;@8349
	sub bl, 3Ch	;@834B
DungeonLoop_Wait:	call KeyReady	; key waiting?	;@834E
	jne DungeonLoop_Key	;@8351
	mov ah, 2Ch	;@8353
	int 21h	;@8355
	cmp bl, dh	;@8357
	jne DungeonLoop_Wait	;@8359
	mov ax, 3920h	; timeout: Space = Pass	;@835B
	jmp short DungeonLoop_Find	;@835E
DungeonLoop_Key:	call ReadKey	;@8360
	cmp al, 61h	; 'a'-'z' -> 'A'-'Z'	;@8363
	jb DungeonLoop_Find	;@8365
	cmp al, 7Ah	;@8367
	ja DungeonLoop_Find	;@8369
	sub al, 20h	;@836B
DungeonLoop_Find:	mov cx, 21h	; 33 command keys	;@836D
	lea di, DungeonKeys	;@8370
	repne scasw	; search the key word (scan code, char)	;@8374
	je DungeonLoop_Found	;@8376
	jmp MsgWhat	;@8378
DungeonLoop_Found:	mov bx, 21h	; BX = entry number * 2	;@837B
	sub bx, cx	;@837E
	dec bx	;@8380
	shl bx, 1	;@8381
	lea si, DungeonPrompts	;@8383
	mov si, word ptr [bx+si]	;@8387
	jmp word ptr DungeonCmds[bx]	;@8389
;------------------------------------------------------------------------------
; DungeonTurnEnd: every dungeon command ends here (MainLoop jumps here while Location =
; 1). Adds the party size to the move count, eats food, burns a torch turn, redraws the header
; and the view. On an empty cell (00) a wandering monster may come: chance (DungeonLevel + 2) in
; (DungeonLevel + 130); its kind is 18h + Random(level + 2), at most 1Eh (Orc ... Balron), the
; cell becomes 40h (a chest, after the fight) and StartCombat fights it. Cells 1-8 (7 excepted)
; run the event handler of the table at DungeonEventCmds with BX = the cell's address.
;------------------------------------------------------------------------------
DungeonTurnEnd:	mov al, byte ptr PartySize	;@838D
	call AddMoves	;@8390
	call PartyUpkeep	; food (PARTY 6FDF)	;@8393
	cmp byte ptr LightOn, 0	;@8396
	je DungeonTurn_View	;@839B
	dec byte ptr LightOn	; a torch turn	;@839D
DungeonTurn_View:	call PrintLevelHead	;@83A1
	call DrawDungeon	; the 3D view	;@83A4
	mov bx, word ptr PlayerXY	;@83A7
	call DungeonCell	; AL = cell under the party, BX = its address	;@83AB
	cmp al, 0	;@83AE
	jne DungeonTurn_Event	;@83B0
	mov dh, 82h	; Random(82h + level) ...	;@83B2
	add dh, byte ptr DungeonLevel	;@83B4
	call Random	;@83B8
	shl dl, 1	; ... >= 80h: a monster	;@83BB
	jae DungeonTurn_Done	;@83BD
	mov dh, byte ptr DungeonLevel	;@83BF
	add dh, 2	;@83C3
	call Random	;@83C6
	cmp dl, 7	; at most 6	;@83C9
	jb DungeonTurn_SetFoe	;@83CC
	mov dl, 6	;@83CE
DungeonTurn_SetFoe:	add dl, 18h	; Orc (18h) ... Balron (1Eh)	;@83D0
	mov byte ptr FoeTile, dl	; FoeTile	;@83D3
	mov byte ptr [bx], 40h	; a chest where it stood	;@83D7
	jmp StartCombat	; StartCombat	;@83DA
DungeonTurn_Event:	cmp al, 8	; only cells 1-8 are events	;@83DD
	ja DungeonTurn_Done	;@83DF
	cmp al, 7	; 7: none	;@83E1
	je DungeonTurn_Done	;@83E3
	dec al	;@83E5
	mov ah, 0	;@83E7
	shl ax, 1	;@83E9
	mov si, ax	;@83EB
	call FlushKeys	;@83ED
; 1 time, 2 fountain, 3 wind, 4 trap, 5 rod, 6 gremlins, 8 writing
	jmp word ptr DungeonEventCmds[si]	;@83F0
DungeonTurn_Done:	jmp DungeonLoop	;@83F4
;------------------------------------------------------------------------------
; CmdKlimb: up a ladder (cell bit 10h); from level 1 out of the dungeon (SHRINE 6458).
;------------------------------------------------------------------------------
CmdKlimb:	call PrintMsg	;@83F7
	mov bx, word ptr PlayerXY	;@83FA
	call DungeonCell	;@83FE
	and al, 10h	; ladder up?	;@8401
	je Klimb_Invalid	;@8403
	cmp byte ptr DungeonLevel, 0	;@8405
	je Klimb_Exit	;@840A
	dec byte ptr DungeonLevel	;@840C
	jmp DungeonTurnEnd	;@8410
Klimb_Invalid:	jmp MsgInvalidMove	;@8413
Klimb_Exit:	call ExitToSosaria	; back to Sosaria	;@8416
	jmp MainLoop	;@8419
;------------------------------------------------------------------------------
; CmdDescend: down a ladder (cell bit 20h, not a wall kind).
;------------------------------------------------------------------------------
CmdDescend:	call PrintMsg	;@841C
	mov bx, word ptr PlayerXY	;@841F
	call DungeonCell	;@8423
	test al, 0FFh	;@8426
	js Descend_Invalid	; 80h and up: no	;@8428
	and al, 20h	; ladder down?	;@842A
	je Descend_Invalid	;@842C
	inc byte ptr DungeonLevel	;@842E
	jmp DungeonTurnEnd	;@8432
Descend_Invalid:	jmp MsgInvalidMove	;@8435
;------------------------------------------------------------------------------
; CmdTurnRight, CmdTurnLeft: turn, unless the party stands in a cell A0h or
; above (a door).
;------------------------------------------------------------------------------
CmdTurnRight:	call PrintMsg	;@8438
	mov bx, word ptr PlayerXY	;@843B
	call DungeonCell	;@843F
	cmp al, 0A0h	; door cell: no turning	;@8442
	jae TurnRight_Invalid	;@8444
	inc byte ptr Facing	; clockwise	;@8446
	and byte ptr Facing, 3	;@844A
	jmp DungeonTurnEnd	;@844F
TurnRight_Invalid:	jmp MsgInvalidMove	;@8452
CmdTurnLeft:	call PrintMsg	;@8455
	mov bx, word ptr PlayerXY	;@8458
	call DungeonCell	;@845C
	cmp al, 0A0h	; door cell: no turning	;@845F
	jae TurnLeft_Invalid	;@8461
	dec byte ptr Facing	; anticlockwise	;@8463
	and byte ptr Facing, 3	;@8467
	jmp DungeonTurnEnd	;@846C
TurnLeft_Invalid:	jmp MsgInvalidMove	;@846F
;------------------------------------------------------------------------------
; CmdNotDungeon: the surface commands that do nothing here: "Not a DNG cmd!", buzz.
;------------------------------------------------------------------------------
CmdNotDungeon:	call PrintMsg	;@8472
	mov al, 0FFh	; buzz sound	;@8475
	call Sound	;@8477
	jmp DungeonTurnEnd	;@847A
;------------------------------------------------------------------------------
; CmdAdvance: one step forward (FacingDxTbl/FacingDyTbl: x and y step by facing, wrapping at 16);
; only a wall (exactly 80h) stops it, so the door kinds (A0h, C0h) can be entered.
;------------------------------------------------------------------------------
CmdAdvance:	call PrintMsg	;@847D
	mov bl, byte ptr Facing	;@8480
	mov bh, 0	;@8484
	mov dx, word ptr PlayerXY	;@8486
	add dl, byte ptr FacingDxTbl[bx]	; x step for this facing	;@848A
	add dh, byte ptr FacingDyTbl[bx]	; y step	;@848E
	and dx, 0F0Fh	; the level wraps round	;@8492
	mov bx, dx	;@8496
	call DungeonCell	;@8498
	cmp al, 80h	; wall?	;@849B
	je Advance_Invalid	;@849D
	mov word ptr PlayerXY, dx	;@849F
	jmp DungeonTurnEnd	;@84A3
Advance_Invalid:	jmp MsgInvalidMove	;@84A6
;------------------------------------------------------------------------------
; CmdRetreat: one step back; any cell with bit 7 (wall or door) stops it.
;------------------------------------------------------------------------------
CmdRetreat:	call PrintMsg	;@84A9
	mov bl, byte ptr Facing	;@84AC
	add bl, 2	; the opposite facing	;@84B0
	and bl, 3	;@84B3
	mov bh, 0	;@84B6
	mov dx, word ptr PlayerXY	;@84B8
	add dl, byte ptr FacingDxTbl[bx]	;@84BC
	add dh, byte ptr FacingDyTbl[bx]	;@84C0
	and dx, 0F0Fh	;@84C4
	mov bx, dx	;@84C8
	call DungeonCell	;@84CA
	rol al, 1	; bit 7: wall or door	;@84CD
	jb Retreat_Invalid	;@84CF
	mov word ptr PlayerXY, dx	;@84D1
	jmp DungeonTurnEnd	;@84D5
Retreat_Invalid:	jmp MsgInvalidMove	;@84D8
CODE ENDS
END
